"""日志分析器。"""
import re
from collections import Counter
from pathlib import Path

LINE_RE = re.compile(r"^(?P<ts>\S+ \S+) \[(?P<level>\w+)\] (?P<msg>.*)$")

def parse_file(path: str) -> list[dict]:
    """解析日志文件为结构化记录。"""
    records = []
    for line in Path(path).read_text(encoding="utf-8").splitlines():
        m = LINE_RE.match(line)
        if m:
            records.append(m.groupdict())
    return records

def summarize(records: list[dict]) -> dict:
    """统计各等级数量。"""
    return dict(Counter(r["level"] for r in records))

def main() -> None:
    """入口：读取 sample.log 并打印统计。"""
    records = parse_file("sample.log")
    print(summarize(records))

if __name__ == "__main__":
    main()

"""待办事项 Web API。"""
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI(title="Todo API", version="1.0.0")
_db: dict[int, dict] = {}
_next_id = 0

class TodoIn(BaseModel):
    """创建/更新请求体。"""
    title: str = Field(min_length=1, max_length=100)
    done: bool = False

@app.post("/api/todos", status_code=201)
async def create(todo: TodoIn) -> dict:
    """创建待办。"""
    global _next_id
    _next_id += 1
    _db[_next_id] = {"id": _next_id, **todo.model_dump()}
    return {"success": True, "data": _db[_next_id], "message": "创建成功"}

@app.get("/api/todos")
async def listing() -> dict:
    """列出全部待办。"""
    return {"success": True, "data": list(_db.values())}

@app.delete("/api/todos/{todo_id}")
async def remove(todo_id: int) -> dict:
    """删除待办。"""
    if todo_id not in _db:
        raise HTTPException(status_code=404, detail="未找到该待办")
    _db.pop(todo_id)
    return {"success": True, "data": {"id": todo_id}, "message": "已删除"}
